#include <stdio.h>
#include <stdint.h>
#include <stddef.h>

/* Kaydedici blogu taklidi (gercekte 0x40004400'e eslenir) */
typedef struct {
    volatile uint8_t  CR;    /* denetim     */
    volatile uint32_t DR;    /* veri        */
    volatile uint8_t  SR;    /* durum       */
    volatile uint16_t BRR;   /* baud bolucu */
} UART_T;

#define CR_EN    (1u << 0)
#define CR_TXIE  (1u << 1)
#define CR_RXIE  (1u << 3)
#define CFG_MODE (3u << 4)   /* 2 bitlik alan */

int main(void)
{
    UART_T u = {0};
    printf("sizeof=%lu DR=%lu SR=%lu BRR=%lu\n",
           (unsigned long)sizeof(UART_T),
           (unsigned long)offsetof(UART_T, DR),
           (unsigned long)offsetof(UART_T, SR),
           (unsigned long)offsetof(UART_T, BRR));

    u.CR |= CR_EN;
    u.CR |= CR_RXIE;
    u.CR &= (uint8_t)~CR_TXIE;
    printf("CR=0x%02X\n", u.CR);

    uint32_t cfg = 0xFFFFFFFFu;
    cfg = (cfg & ~CFG_MODE) | (2u << 4);
    printf("cfg=0x%08lX\n", (unsigned long)cfg);
    return 0;
}

#include <stdio.h>
#include <stdint.h>

#define N 8                     /* ikinin kuvveti olmali */
static volatile uint8_t buf[N];
static volatile uint8_t head = 0;   /* ISR yazar       */
static volatile uint8_t tail = 0;   /* ana dongu okur  */

static int rb_put(uint8_t c)        /* ISR tarafi */
{
    uint8_t nh = (uint8_t)((head + 1u) & (N - 1u));
    if (nh == tail) return 0;       /* dolu: veriyi at */
    buf[head] = c;
    head = nh;
    return 1;
}

static int rb_get(uint8_t *c)       /* ana dongu tarafi */
{
    if (head == tail) return 0;
    *c = buf[tail];
    tail = (uint8_t)((tail + 1u) & (N - 1u));
    return 1;
}

int main(void)
{
    int kayip = 0;
    for (int i = 1; i <= 10; i++)
        if (!rb_put((uint8_t)i)) kayip++;

    printf("doluluk=%u kayip=%d\n",
           (unsigned)((head - tail) & (N - 1u)), kayip);

    uint8_t c;
    int n = 0;
    unsigned sum = 0;
    while (rb_get(&c)) { sum += c; n++; }

    printf("okunan=%d toplam=%u\n", n, sum);
    printf("bos=%d\n", head == tail);
    return 0;
}

