#define N 5

/* Oncelik sirasina gore (periyot kucuk = oncelik yuksek), ms */
static const double C[N]  = { 0.4, 1.2, 8.0, 3.0, 4.0 };
static const double T[N]  = { 2.0, 10.0, 25.0, 50.0, 100.0 };
static const char *AD[N]  = { "t1", "t2", "t5", "t3", "t4" };

int main(void)
{
    double U = 0.0;
    for (int i = 0; i < N; i++) U += C[i] / T[i];

    double lim = N * (pow(2.0, 1.0 / N) - 1.0);
    printf("U=%.4f sinir=%.4f yeterli_kosul=%s\n",
           U, lim, (U <= lim) ? "SAGLANDI" : "SAGLANMADI");

    int tamam = 1;
    for (int i = 0; i < N; i++) {
        double R = C[i], prev = -1.0;
        while (R != prev) {                 /* tepki suresi yinelemesi */
            prev = R;
            double s = C[i];
            for (int j = 0; j < i; j++)
                s += ceil(prev / T[j]) * C[j];
            R = s;
            if (R > T[i]) break;
        }
        if (R > T[i]) tamam = 0;
        printf("%s: R=%6.2f D=%6.2f %s\n", AD[i], R, T[i],
               (R <= T[i]) ? "tamam" : "KACIRDI");
    }
    printf("karar=%s\n", tamam ? "cizelgelenebilir" : "cizelgelenemez");
    return 0;
}

#include <stdio.h>

#define NT 2
#define HOR 35          /* LCM(5,7) = 35 ms */

static const int C[NT] = { 2, 4 };
static const int T[NT] = { 5, 7 };

/* mode 0 = RM (periyot kucuk once), 1 = EDF (son tarih erken once) */
static int sim(int mode)
{
    int kalan[NT] = { 0, 0 };
    int sontarih[NT] = { 0, 0 };
    int kacirma = 0;

    for (int t = 0; t < HOR; t++) {
        for (int i = 0; i < NT; i++)
            if (t % T[i] == 0) { kalan[i] = C[i]; sontarih[i] = t + T[i]; }

        int sec = -1;
        for (int i = 0; i < NT; i++) {
            if (kalan[i] <= 0) continue;
            if (sec < 0) { sec = i; continue; }
            int daha_iyi = (mode == 0) ? (T[i] < T[sec])
                                       : (sontarih[i] < sontarih[sec]);
            if (daha_iyi) sec = i;
        }
        if (sec >= 0) kalan[sec]--;

        for (int i = 0; i < NT; i++)
            if (kalan[i] > 0 && sontarih[i] == t + 1) { kacirma++; kalan[i] = 0; }
    }
    return kacirma;
}

int main(void)
{
    double U = 0.0;
    for (int i = 0; i < NT; i++) U += (double)C[i] / T[i];
    printf("U=%.4f\n", U);
    printf("RM  kacirma=%d\n", sim(0));
    printf("EDF kacirma=%d\n", sim(1));
    return 0;
}

#include <stdio.h>

/* tH(C=1,T=5) > tM(C=6,T=25) > tL(C=4,T=100)
   tL ile tH ayni kaynagi paylasiyor; tL'nin kritik bolgesi 3 ms.
   tM kaynagi kullanmiyor ama tL'yi on aliyor. */

#define CH 1.0
#define TH 5.0
#define CM 6.0
#define CS 3.0

static void karar(const char *ad, double B)
{
    double R = CH + B;
    printf("%s: B=%4.1f R=%4.1f D=%4.1f %s\n", ad, B, R, TH,
           (R <= TH) ? "tamam" : "KACIRDI");
}

int main(void)
{
    karar("devralma-yok(tM 1 kez)", CS + 1 * CM);
    karar("devralma-yok(tM 2 kez)", CS + 2 * CM);
    karar("PIP                   ", CS);

    double cs[3] = { 3.0, 2.0, 1.5 };
    double toplam = 0.0, enbuyuk = 0.0;
    for (int i = 0; i < 3; i++) {
        toplam += cs[i];
        if (cs[i] > enbuyuk) enbuyuk = cs[i];
    }
    printf("PIP ust siniri=%.1f ms  PCP ust siniri=%.1f ms\n", toplam, enbuyuk);
    return 0;
}

