#define YSIZE 512
#define DESEN 0xA5u

static uint8_t yigit[YSIZE];

/* Yigit yukaridan asagiya buyur: sondan basa dogru yaziyoruz. */
static void gorev_kos(int derinlik)
{
    for (int i = 0; i < derinlik; i++)
        yigit[YSIZE - 1 - i] = (uint8_t)(i & 0xFF);
}

static int su_izi(void)
{
    int bozulmamis = 0;
    for (int i = 0; i < YSIZE; i++) {
        if (yigit[i] != DESEN) break;   /* dipten yukari ilk bozulma */
        bozulmamis++;
    }
    return bozulmamis;
}

int main(void)
{
    memset(yigit, DESEN, YSIZE);        /* yigit boyandi */
    gorev_kos(148);                     /* en derin calisma */

    int bozulmamis = su_izi();
    int kullanilan = YSIZE - bozulmamis;
    printf("bozulmamis=%d kullanilan=%d\n", bozulmamis, kullanilan);
    printf("doluluk=%d%%\n", (100 * kullanilan) / YSIZE);
    printf("pay=%d bayt\n", bozulmamis);
    printf("tasma=%s\n", (bozulmamis == 0) ? "RISK" : "yok");
    return 0;
}

