/* Akimlar nA, sureler us; yuk nA*us olarak toplanir. */
typedef struct { const char *ad; uint32_t akim_nA; uint32_t sure_us; } Dilim;

static const Dilim d[] = {
    { "aktif 48 MHz",   8500000u,   6000u },
    { "dusuk guc",      1200000u,  14000u },
    { "derin uyku",        3500u, 980000u },
};
#define N (sizeof d / sizeof d[0])

int main(void)
{
    uint64_t yuk = 0, sure = 0;
    for (unsigned i = 0; i < N; i++) {
        yuk  += (uint64_t)d[i].akim_nA * d[i].sure_us;
        sure += d[i].sure_us;
    }
    uint32_t iort_nA = (uint32_t)(yuk / sure);
    printf("cevrim=%llu us Iort=%u nA\n", (unsigned long long)sure, iort_nA);

    uint64_t kap_nAh = 2200ull * 1000000ull;      /* 2200 mAh */
    uint32_t saat = (uint32_t)(kap_nAh / iort_nA);
    printf("omur=%u saat=%u gun\n", saat, saat / 24);

    uint32_t iort2 = iort_nA + 15000u;            /* LDO bosta 15 uA */
    uint32_t saat2 = (uint32_t)(kap_nAh / iort2);
    printf("LDO ile Iort=%u nA omur=%u saat\n", iort2, saat2);
    printf("kayip=%u %%\n", 100u - (100u * saat2) / saat);
    return 0;
}

#include <stdio.h>
#include <stdint.h>

/* Q8 sabit nokta: tamsayi = gercek * 256.  Kp=2,00  Ki=0,25  Kd=1,00 */
#define Q      8
#define KP   512
#define KI    64
#define KD   256
#define UMAX 300
#define UMIN   0

static int32_t pid(int32_t hedef, int32_t olcum, int antiwindup,
                   int32_t *integral, int32_t *e_eski, int *doygun_sayaci)
{
    int32_t e = hedef - olcum;
    int32_t d = e - *e_eski;
    int32_t i_deneme = *integral + e;

    int32_t u = (KP * e + KI * i_deneme + KD * d) >> Q;

    int doygun = (u > UMAX) || (u < UMIN);
    if (u > UMAX) u = UMAX;
    if (u < UMIN) u = UMIN;
    if (doygun) (*doygun_sayaci)++;

    /* Kosullu integrasyon: cikis doygunken integrali buyutme */
    if (!antiwindup || !doygun) *integral = i_deneme;

    *e_eski = e;
    return u;
}

int main(void)
{
    const int32_t hedef = 100;
    const int32_t olcum[8] = { 0, 0, 0, 0, 0, 0, 100, 100 };

    for (int aw = 0; aw <= 1; aw++) {
        int32_t integral = 0, e_eski = 0;
        int doygun = 0;
        printf("aw=%d u:", aw);
        for (int k = 0; k < 8; k++)
            printf(" %ld", (long)pid(hedef, olcum[k], aw, &integral, &e_eski, &doygun));
        printf("  integral=%ld doygun=%d\n", (long)integral, doygun);
    }

    /* Q8 EMA filtre: y += alpha*(x-y), alpha = 12/256 ~ 0,0469 */
    int32_t y = 0;
    printf("EMA:");
    for (int k = 0; k < 6; k++) {
        y += (12 * ((100 << Q) - y)) >> Q;
        printf(" %ld", (long)(y >> Q));
    }
    printf("\n");
    return 0;
}

#include <stdio.h>
#include <stdint.h>

/* Q8.8: int16_t icinde 8 kesir biti; 1,0 = 256, cozunurluk 1/256 */
#define Q      8
#define ONE   (1 << Q)
#define QMAX  32767
#define QMIN (-32768)

static int16_t doyur(int32_t v)
{
    if (v > QMAX) return (int16_t)QMAX;
    if (v < QMIN) return (int16_t)QMIN;
    return (int16_t)v;
}

static int16_t q_mul_kes(int16_t a, int16_t b)          /* kesme */
{
    return doyur(((int32_t)a * b) >> Q);
}

static int16_t q_mul_yuvarla(int16_t a, int16_t b)      /* yuvarlama */
{
    return doyur((((int32_t)a * b) + (1 << (Q - 1))) >> Q);
}

static void yaz(const char *ad, int16_t q)
{
    int32_t mili = ((int32_t)q * 1000) / 256;
    printf("%s=%ld(%ld.%03ld)\n", ad, (long)q, (long)(mili / 1000),
           (long)((mili < 0 ? -mili : mili) % 1000));
}

int main(void)
{
    int16_t a = 640;        /* 2,50  */
    int16_t b = 832;        /* 3,25  */
    yaz("a*b", q_mul_kes(a, b));

    int16_t c = 25600;      /* 100,0 */
    int16_t d = 512;        /* 2,0   */
    yaz("c*d", q_mul_kes(c, d));          /* 200 > 127,996 -> doyar */

    int16_t x = 85;         /* 0,3320 */
    int16_t y = 102;        /* 0,3984 */
    printf("kes=%d yuvarla=%d\n", q_mul_kes(x, y), q_mul_yuvarla(x, y));

    int32_t top = 0;
    for (int k = 0; k < 1000; k++) top += ONE / 3;   /* her adim 85, ideal 85,333 */
    int32_t ideal = 1000L * ONE / 3;
    printf("ideal=%ld kes=%ld hata=%ld LSB = %ld.%02ld birim\n",
           (long)ideal, (long)top, (long)(ideal - top),
           (long)((ideal - top) / 256), (long)((100L * ((ideal - top) % 256)) / 256));
    return 0;
}

#include <stdio.h>

/* Pencereli bekci kopegi: besleme [ALT, UST] araliginda olmali. */
#define ALT 22
#define UST 78
#define TUM_BAYRAKLAR 0x07u

static const int t[]      = { 45, 70, 12, 95, 50, 40 };   /* son beslemeden gecen ms */
static const unsigned b[] = { 0x07, 0x07, 0x07, 0x07, 0x03, 0x07 };

int main(void)
{
    int reset = 0;
    for (unsigned k = 0; k < sizeof t / sizeof t[0]; k++) {
        const char *sonuc;
        if (b[k] != TUM_BAYRAKLAR)      sonuc = "BESLEME-YOK(bayrak)";
        else if (t[k] < ALT)            sonuc = "RESET(erken)";
        else if (t[k] > UST)            sonuc = "RESET(gec)";
        else                            sonuc = "besle";
        if (sonuc[0] == 'R' || sonuc[0] == 'B') reset++;
        printf("t=%2d ms bayrak=0x%02X -> %s\n", t[k], b[k], sonuc);
    }
    printf("reset/ihlal sayisi=%d\n", reset);
    return 0;
}

#include <stdio.h>
#include <stdint.h>

/* ---- HAL: gercekte kaydediciler, testte sahte degiskenler ---- */
static volatile uint32_t ODR;      /* cikis veri kaydedicisi */
static volatile uint32_t TIK_MS;   /* sistem tiki (enjekte edilir) */

static void hal_pin(int no, int deger)
{
    if (deger) ODR |=  (1u << no);
    else       ODR &= ~(1u << no);
}
static uint32_t hal_tik(void) { return TIK_MS; }

/* ---- Test edilen birim: sarmaya dayanikli periyot kontrolu ---- */
static int zamani_geldi(uint32_t *son, uint32_t periyot)
{
    uint32_t simdi = hal_tik();
    if ((uint32_t)(simdi - *son) >= periyot) { *son = simdi; return 1; }
    return 0;
}

/* ---- Kucuk test kosumu ---- */
static int gecti, kaldi;
static void ESIT(const char *ad, long beklenen, long gercek)
{
    if (beklenen == gercek) { gecti++; printf("PASS %s\n", ad); }
    else { kaldi++; printf("FAIL %s beklenen=%ld gercek=%ld\n", ad, beklenen, gercek); }
}

int main(void)
{
    uint32_t son = 0;

    TIK_MS = 50;   ESIT("erken-cagri", 0, zamani_geldi(&son, 100));
    TIK_MS = 100;  ESIT("tam-periyot", 1, zamani_geldi(&son, 100));
    ESIT("son-guncellendi", 100, (long)son);

    /* 32 bit ms sayacinin sarmasi: 49,7 gun sonrasi */
    son = 0xFFFFFFF0u; TIK_MS = 5;
    ESIT("sarma", 1, zamani_geldi(&son, 10));

    /* HAL uzerinden kaydedici testi */
    ODR = 0;
    hal_pin(3, 1); hal_pin(5, 1); hal_pin(3, 0);
    ESIT("ODR", 0x20, (long)ODR);

    printf("ozet: %d gecti, %d kaldi\n", gecti, kaldi);
    return kaldi ? 1 : 0;
}
